<script setup lang="ts">import { onMounted, ref } from 'vue';import { ArrowLeft, RotateCcw } from 'lucide-vue-next';import AppShell from '@/components/AppShell.vue';import { memoryService,type Memory } from '@/services/memory-service';import { useAppStore } from '@/stores/app';const memories=ref<Memory[]>([]),app=useAppStore();async function reload(){memories.value=await memoryService.trashList()}onMounted(reload);async function restore(id:string){await memoryService.restore(id);app.showToast('Memory dipulihkan');reload()}</script>
<template><AppShell><div class="page"><button class="icon-button -ml-3" @click="$router.back()"><ArrowLeft /></button><h1 class="mt-7 text-3xl font-semibold tracking-[-.035em]">Trash</h1><p class="mt-2 text-sm text-muted">Memory di sini dapat dipulihkan.</p><div v-if="memories.length" class="mt-7 divide-y divide-line"><div v-for="memory in memories" :key="memory.id" class="flex items-center justify-between gap-4 py-4"><div><p class="font-semibold">{{memory.title}}</p><p class="mt-1 text-sm text-muted">Dihapus baru saja</p></div><button class="soft-button min-h-10 rounded-xl px-3" @click="restore(memory.id)"><RotateCcw :size="16"/>Restore</button></div></div><section v-else class="mt-20 text-center"><p class="font-semibold">Trash kosong.</p><p class="mt-2 text-sm text-muted">Memory yang kamu hapus akan muncul di sini.</p></section></div></AppShell></template>
